import{_ as a,C as r,o as d,c as n,aj as s,E as e}from"./framework.js";const S=JSON.parse('{"title":"SQL 日志 | Cms / Database | Documentation","description":"SQL 日志用于查看站点脚本通过 k.DB.sqlite / k.DB.mysql / k.DB.sqlServer 执行的 SQL 语句：含语句正文、参数、耗时与数据库类型，便于排障与审计。本页为 只读 观测，不提供删除或编辑日志；也无对应 k. 写入 API。","frontmatter":{"title":"SQL 日志 | Cms / Database | Documentation","description":"SQL 日志用于查看站点脚本通过 k.DB.sqlite / k.DB.mysql / k.DB.sqlServer 执行的 SQL 语句：含语句正文、参数、耗时与数据库类型，便于排障与审计。本页为 只读 观测，不提供删除或编辑日志；也无对应 k. 写入 API。","head":[["link",{"rel":"canonical","href":"https://docs.kooboo.com/zh/cms/database/sql-logs.html"}]]},"headers":[],"relativePath":"zh/cms/database/sql-logs.md","filePath":"cms/database/sql-logs.md","lastUpdated":1780650820000}'),i={name:"zh/cms/database/sql-logs.md"};function l(g,t,h,c,p,k){const o=r("DocImage");return d(),n("div",null,[t[0]||(t[0]=s('<h1 id="sql-日志" tabindex="-1">SQL 日志 <a class="header-anchor" href="#sql-日志" aria-label="Permalink to &quot;SQL 日志&quot;">​</a></h1><blockquote><p>菜单：<strong>数据库 → SQL 日志</strong><br> 深链：<code>/_Admin/database/sql-logs?SiteId={站点GUID}</code></p></blockquote><p><strong>SQL 日志</strong>用于查看站点脚本通过 <strong><code>k.DB.sqlite</code> / <code>k.DB.mysql</code> / <code>k.DB.sqlServer</code></strong> 执行的 SQL 语句：含语句正文、参数、耗时与数据库类型，便于排障与审计。本页为 <strong>只读</strong> 观测，不提供删除或编辑日志；也无对应 <code>k.*</code> 写入 API。</p><div class="tip custom-block"><p class="custom-block-title">权限</p><p>查看本页及列表数据：<code>database·log</code>（<code>database</code> 功能的 <strong>log</strong> 动作）。<br> 工具栏右侧 <strong>启用</strong> 开关会保存站点设置，通常需站点 <strong>编辑</strong> 类权限（与保存站点配置一致）。</p></div><div class="warning custom-block"><p class="custom-block-title">记录范围</p><table tabindex="0"><thead><tr><th>会记录</th><th>不会记录</th></tr></thead><tbody><tr><td><code>k.DB.sqlite.query</code> / <code>execute</code> 等触发的 SQL</td><td><a href="./table.html">IndexedDB 表</a>（<code>k.DB.indexedDb</code>）操作</td></tr><tr><td><code>k.DB.mysql</code>、<code>k.DB.sqlServer</code> 的 SQL</td><td><a href="./key-value.html">键值存储</a>（<code>k.DB.keyValue</code>）</td></tr><tr><td>后台 <strong>SQLite / MySQL / SQL Server 表</strong> 维护时经脚本层执行的 SQL（若走同一执行器）</td><td>未开启 <strong>SQL 日志</strong> 时的任何 SQL</td></tr></tbody></table><p>须先在站点开启 <strong>SQL 日志</strong>（见 <a href="#启用-sql-日志">启用日志</a>），之后产生的 SQL 才会写入日志。</p></div><h2 id="如何打开" tabindex="-1">如何打开 <a class="header-anchor" href="#如何打开" aria-label="Permalink to &quot;如何打开&quot;">​</a></h2><ol><li>在 <a href="./../navigation.html#权限与编辑菜单">编辑菜单</a> 中勾选 <strong>数据库 → SQL 日志</strong>。</li><li>左侧 <strong>数据库 → SQL 日志</strong>。</li></ol>',7)),e(o,{src:"/cms/database/sql-logs-overview.png",alt:"SQL 日志页",width:"1120"}),t[1]||(t[1]=s('<h2 id="启用-sql-日志" tabindex="-1">启用 SQL 日志 <a class="header-anchor" href="#启用-sql-日志" aria-label="Permalink to &quot;启用 SQL 日志&quot;">​</a></h2><p>站点级开关 <strong><code>enableSqlLog</code></strong>，两处等价（改一处即可）：</p><table tabindex="0"><thead><tr><th>位置</th><th>路径</th></tr></thead><tbody><tr><td><strong>本页工具栏</strong></td><td>右侧 <strong>启用</strong> 开关，切换后立即保存站点</td></tr><tr><td><strong>站点设置 → 高级</strong></td><td><code>/_Admin/system/settings?SiteId={站点GUID}&amp;name=advance</code>，<strong>SQL 日志</strong> 项</td></tr></tbody></table><p>关闭后，新的脚本 SQL <strong>不再</strong> 写入日志；已产生的历史周次数据仍可按周查看。</p>',4)),e(o,{src:"/cms/database/sql-logs-toolbar.png",alt:"SQL 日志筛选与启用开关",width:"1120"}),t[2]||(t[2]=s('<h2 id="筛选与搜索" tabindex="-1">筛选与搜索 <a class="header-anchor" href="#筛选与搜索" aria-label="Permalink to &quot;筛选与搜索&quot;">​</a></h2><p>工具栏从左到右：</p><table tabindex="0"><thead><tr><th>控件</th><th>说明</th></tr></thead><tbody><tr><td><strong>周</strong></td><td>按 <strong>自然周</strong> 选择日志文件；选项文案为 <code>yyyy-MM-dd~yyyy-MM-dd</code>（该周起止日期）。仅列出 <strong>当前站点在该周有条目</strong> 的周；若尚无记录，默认显示 <strong>当前周</strong></td></tr><tr><td><strong>类型</strong></td><td>可选 <strong>SQLite</strong>、<strong>MySQL</strong>、<strong>SQLServer</strong>（对应 <code>sqlite</code> / <code>mysql</code> / <code>sqlserver</code>）；清空表示全部类型</td></tr><tr><td><strong>关键字</strong></td><td>在 <strong>SQL 正文</strong> 中模糊匹配（不区分大小写）；输入后约 1 秒防抖再查询；清空即刷新</td></tr><tr><td><strong>启用</strong></td><td>见 <a href="#启用-sql-日志">启用 SQL 日志</a></td></tr></tbody></table><p>切换 <strong>周</strong>、<strong>类型</strong> 或关键字会重新请求 <code>SqlLog/List</code> 并回到第 1 页。</p><h2 id="日志列表" tabindex="-1">日志列表 <a class="header-anchor" href="#日志列表" aria-label="Permalink to &quot;日志列表&quot;">​</a></h2><p>分页默认 <strong>50</strong> 条/页（<code>KTable</code> 底部分页切换页码）。</p><table tabindex="0"><thead><tr><th>列</th><th>说明</th></tr></thead><tbody><tr><td><strong>类型</strong></td><td>数据库来源，如 <code>sqlite</code>、<code>mysql</code>、<code>sqlserver</code></td></tr><tr><td><strong>日期时间</strong></td><td>执行时间（站点时区展示）</td></tr><tr><td><strong>执行时间</strong></td><td>耗时，单位 <strong>ms</strong></td></tr><tr><td><strong>内容</strong></td><td>SQL 语句摘要（过长时表格内截断）</td></tr><tr><td><strong>参数</strong></td><td>序列化后的参数对象；无参数或 <code>null</code> 时为空</td></tr><tr><td>行末 <strong>详情</strong></td><td>有数据时打开 <a href="#详情弹窗">详情弹窗</a></td></tr></tbody></table><p>当周尚无记录时，表格显示 <strong>暂无数据</strong>（须已 <strong>启用</strong> 日志且站点内有 <code>k.DB.sqlite</code> 等 SQL 执行）。</p>',8)),e(o,{src:"/cms/database/sql-logs-list.png",alt:"SQL 日志列表",width:"1120"}),t[3]||(t[3]=s(`<h3 id="详情弹窗" tabindex="-1">详情弹窗 <a class="header-anchor" href="#详情弹窗" aria-label="Permalink to &quot;详情弹窗&quot;">​</a></h3><p>点击行末 <strong>眼睛</strong> 图标打开。展示完整 <strong>类型</strong>、<strong>日期时间</strong>、<strong>执行时间</strong>，以及两段完整文本：</p><ol><li><strong>SQL 语句</strong>（可换行）</li><li><strong>参数</strong>（JSON 等序列化结果）</li></ol><p>用于复制完整语句或在慢查询场景下对照参数。</p><h2 id="日志如何产生" tabindex="-1">日志如何产生 <a class="header-anchor" href="#日志如何产生" aria-label="Permalink to &quot;日志如何产生&quot;">​</a></h2><p>脚本访问关系型库时，若 <code>EnableSqlLog</code> 为真，执行器在每次 SQL 完成后异步写入服务端按 <strong>周</strong> 划分的日志文件（站点 <code>AppData</code> 下 <code>SqlLog</code> 目录，文件名如 <code>{年周}.log</code>）。写入与页面列表查询均按 <strong>站点 ID</strong> 过滤，仅能看到本站记录。</p><p>示例（开启日志后）：</p><div class="language-typescript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">typescript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">k.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">DB</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.sqlite.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">query</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;SELECT * FROM logs WHERE id = @id&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, { id: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> })</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">k.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">DB</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.sqlite.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">execute</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;INSERT INTO logs (msg) VALUES (@msg)&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, { msg: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;ok&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> })</span></span></code></pre></div><p>MySQL / SQL Server 须在 <a href="/kb-docs/zh/cms/navigation.html">服务集成</a>（<code>/system/config</code>）中配置连接后，通过 <code>k.DB.mysql</code> / <code>k.DB.sqlServer</code> 执行才会出现对应 <strong>类型</strong> 的日志。</p><div class="info custom-block"><p class="custom-block-title">与后台表维护</p><p><a href="./sqlite-table.html">SQLite 表</a> 列表、列与数据的 <strong>后台 API</strong> 与脚本 <code>k.DB.sqlite</code> 是否为同一条执行链，以实际环境为准。排障脚本 SQL 时，以本页 <strong>类型</strong> 与 <strong>内容</strong> 列为准；若后台操作未产生日志，请确认是否经由 <code>k.DB.*</code> 执行且已 <strong>启用</strong> 日志。</p></div><h2 id="典型工作流" tabindex="-1">典型工作流 <a class="header-anchor" href="#典型工作流" aria-label="Permalink to &quot;典型工作流&quot;">​</a></h2><ol><li>在 <strong>高级</strong> 或本页打开 <strong>SQL 日志</strong>。</li><li>复现问题（访问会执行 <code>k.DB.sqlite</code> 等的页面或定时任务）。</li><li>选择对应 <strong>周</strong>，按 <strong>类型</strong> / <strong>关键字</strong> 缩小范围。</li><li>打开 <strong>详情</strong> 复制 SQL 与参数，回到 Code 或数据库工具验证。</li><li>生产环境长期开启可能增加 I/O 与磁盘占用，排障结束后可关闭 <strong>启用</strong>。</li></ol><h2 id="相关" tabindex="-1">相关 <a class="header-anchor" href="#相关" aria-label="Permalink to &quot;相关&quot;">​</a></h2><table tabindex="0"><thead><tr><th>文档</th><th>说明</th></tr></thead><tbody><tr><td><a href="./">数据库概述</a></td><td>菜单与权限</td></tr><tr><td><a href="./sqlite-table.html">SQLite 表</a></td><td>内置 SQLite 与 CSV</td></tr><tr><td><a href="/kb-docs/zh/api/sqlite/">k.DB.sqlite</a></td><td>脚本 SQL API</td></tr><tr><td><a href="/kb-docs/zh/api/database/">k.DB</a></td><td>数据库总览</td></tr></tbody></table>`,14))])}const q=a(i,[["render",l]]);export{S as __pageData,q as default};
